114	        if (isTelephoneInUse(normalizedTelephone)) {
115	            throw new DuplicateTelephoneException(
116	                "An owner with telephone " + normalizedTelephone + " already exists");
117	        }
118	        this.clinicService.saveOwner(owner);
119	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
120	        headers.setLocation(UriComponentsBuilder.newInstance()
121	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
122	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
123	    }
124	
125	    /**
126	     * Removes every non-digit character from the supplied telephone value.
127	     *
128	     * @param telephone the raw telephone value (may be {@code null})
129	     * @return the telephone stripped down to its digits, or {@code null} if the input was {@code null}
130	     */
131	    private String normalizeTelephone(String telephone) {
