139	     *
140	     * @param email the email value (may be {@code null})
141	     * @return the lower-cased email, or {@code null} if the input was {@code null}
142	     */
143	    private String normalizeEmail(String email) {
144	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
