156	        if (normalizedTelephone == null) {
157	            return false;
158	        }
159	        return this.clinicService.findAllOwners().stream()
160	            .map(Owner::getTelephone)
161	            .map(this::normalizeTelephone)
162	            .anyMatch(normalizedTelephone::equals);
163	    }
